// not know. Use a type switch. A webhook endpoint receives a WebhookEvent: see UnwrapWebhook.
type Event interface {
	WebhookEvent
	isEvent()
}

func (*DocumentEvent) isEvent() {}

func (*DocumentEvent) isWebhookEvent() {}

// Info returns what every event has: its id, type, environment and creation time.
func (e *DocumentEvent) Info() EventInfo {
	return EventInfo{ID: e.ID, Type: EventType(e.Type), Environment: e.Environment, CreatedAt: e.CreatedAt}
}

func (*CertificateEvent) isEvent() {}

func (*CertificateEvent) isWebhookEvent() {}

// Info returns what every event has: its id, type, environment and creation time.
func (e *CertificateEvent) Info() EventInfo {
	return EventInfo{ID: e.ID, Type: EventType(e.Type), Environment: e.Environment, CreatedAt: e.CreatedAt}
}

func (*AccountEvent) isEvent() {}

func (*AccountEvent) isWebhookEvent() {}

// Info returns what every event has: its id, type, environment and creation time.
func (e *AccountEvent) Info() EventInfo {
	return EventInfo{ID: e.ID, Type: EventType(e.Type), Environment: e.Environment, CreatedAt: e.CreatedAt}
}

// decodeEvent decodes an event of the API into its type, from its type member.
func decodeEvent(data []byte) (Event, error) {
	var head struct {
		Discriminant string `json:"type"`
	}
	if err := json.Unmarshal(data, &head); err != nil {
		return nil, err
	}
	var event Event
	switch head.Discriminant {
	case "invoice.authorized", "invoice.rejected", "purchase_settlement.authorized", "purchase_settlement.rejected", "credit_note.authorized", "credit_note.rejected", "debit_note.authorized", "debit_note.rejected", "waybill.authorized", "waybill.rejected", "withholding.authorized", "withholding.rejected", "document.ride.generated", "document.ride.failed", "document.email.sent", "document.email.delivered", "document.email.bounced", "document.email.complained", "document.email.failed":
		event = new(DocumentEvent)
	case "certificate.verified", "certificate.pending", "certificate.blocked", "certificate.revoked", "certificate.reactivated":
		event = new(CertificateEvent)
	case "account.email_paused", "account.email_resumed":
		event = new(AccountEvent)
	default:
		event = new(UnknownEvent)
	}
	if err := json.Unmarshal(data, event); err != nil {
		return nil, err
	}
	return event, nil
}

// EventListParams holds the query of eventsList (GET /v1/events). Nil members are not sent. Limit
// is the size of each page: List walks every page, so break out of the loop to stop early.
type EventListParams struct {
	// Maximum number of items to return. Default: 20.
	Limit *int

	// The `pagination.nextCursor` of the previous page. Omit it for the first page.
	Cursor *string

	// Only events of this type.
	Type *EventType

	// Only events of this issuer. Format: uuid.
	IssuerID *string

	// Only events of this document. Format: uuid.
	DocumentID *string

	// Only events of this certificate. Format: uuid.
	CertificateID *string
}

// values is the query string of p, without the members that are nil.
func (p *EventListParams) values() url.Values {
	query := url.Values{}
	if p == nil {
		return query
	}
	if p.Limit != nil {
		query.Set("limit", strconv.Itoa(*p.Limit))
	}
	if p.Cursor != nil {
		query.Set("cursor", *p.Cursor)
	}
	if p.Type != nil {
		query.Set("type", string(*p.Type))
	}
	if p.IssuerID != nil {
		query.Set("issuerId", *p.IssuerID)
	}
	if p.DocumentID != nil {
		query.Set("documentId", *p.DocumentID)
	}
	if p.CertificateID != nil {
		query.Set("certificateId", *p.CertificateID)
	}
	return query
}

