// WithholdingForeignPayment: Required when the payment goes abroad (`paymentResidence` is
// `foreign`).
type WithholdingForeignPayment struct {
	// Tax regime of the country of payment: `general`, `tax_haven` or `preferential` (preferential
	// regime or lower-tax jurisdiction).
	Regime WithholdingForeignPaymentRegime `json:"regime"`

	// Country of payment, as the SRI country code (3 or 4 digits).
	Country string `json:"country"`

	// Whether a double taxation treaty applies.
	DoubleTaxationTreatyApplies bool `json:"doubleTaxationTreatyApplies"`

	// Whether the payment is subject to withholding under the law. Required when no double taxation
	// treaty applies.
	SubjectToWithholdingUnderLaw *bool `json:"subjectToWithholdingUnderLaw,omitempty"`

	// Whether it is a payment to a preferential tax regime.
	PreferentialTaxRegime bool `json:"preferentialTaxRegime"`
}

// WithholdingForeignPaymentRegime is a value of the API. Tax regime of the country of payment:
// `general`, `tax_haven` or `preferential` (preferential regime or lower-tax jurisdiction). The API
// may add values: keep a default case.
type WithholdingForeignPaymentRegime string

// The values of WithholdingForeignPaymentRegime.
const (
	WithholdingForeignPaymentRegimeGeneral      WithholdingForeignPaymentRegime = "general"
	WithholdingForeignPaymentRegimeTaxHaven     WithholdingForeignPaymentRegime = "tax_haven"
	WithholdingForeignPaymentRegimePreferential WithholdingForeignPaymentRegime = "preferential"
)

// WithholdingPayment: A payment of the supporting document.
type WithholdingPayment struct {
	// Payment method (same values as `DocumentPayment.method`).
	Method PaymentMethod `json:"method"`

	// Amount. Only the last payment may leave it out: it takes what the other payments leave of the
	// supporting document `total`. With several payments none can be zero (`zero_payment`).
	Amount *string `json:"amount,omitempty"`
}

// WithholdingTax is a value of the API. Tax withheld: `income_tax`, `vat` or `isd`. The API may add
// values: keep a default case.
type WithholdingTax string

// The values of WithholdingTax.
const (
	WithholdingTaxIncomeTax WithholdingTax = "income_tax"
	WithholdingTaxVAT       WithholdingTax = "vat"
	WithholdingTaxIsd       WithholdingTax = "isd"
)
